    # Extract date from note title
    date_str = note['title'].split(" ")[-1]
    date = f"{date_str[:4]}-{date_str[5:7]}-{date_str[8:10]}"  # Format as yyyy-mm-dd

    # Extract habit data from note content
    content_lines = note['content'].split("\n")
    habits = {}

    for line in content_lines:
        if line.startswith("#"):
            continue  # Skip the header line
        if ":" in line:
            habit, value = line.split(":")
            habits[habit.strip()] = value.strip()

    # Add date and habits to the data
    habit_data.append({
        "date": date,
        **habits
    })

print(habit_data)

